import{c as t,Q as n,j as a,g as e}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-10-05T00:00:00.000Z","source":"machiavelli/discourses/book2/05-第五章"},"headers":[],"relativePath":"fragments/2026-10-05.md","filePath":"fragments/2026-10-05.md"}'),r={name:"fragments/2026-10-05.md"};function s(o,l,u,c,p,d){return n(),a("div",null,[...l[0]||(l[0]=[e("p",null,'我写下"新宗派为了赢得名望而消灭旧宗派"的时候，手停住了。我在写的是基督教怎样烧掉异教的诗人和史家，捣毁圣像，把一切带着古代标记的东西都污损掉。格里高利这样的人，为了让自己这一脉站得住，就得让前人的书变成灰。我一边写一边想——我此刻手里的这本《论李维》，几百年后会不会也是某个人为了自己的名望而要烧掉的东西？我不是在替异教抱不平。我是在替所有写书的人害怕。书这种东西，写出来是为了不被忘记，可它偏偏是最容易被忘记的。',-1),e("hr",null,null,-1),e("p",null,'"幸存者都是山民和蛮族，他们不了解古代，也无从把这种知识传给后人。"我读到这句，突然觉得这说的就是我。我懂古代，我懂罗马，可我被扔到了乡下，四周没有人需要我懂得的这些。等我也死了，谁来传下去？更糟的是下一句——"如果幸存者中有人具备这种知识，他也会为了树立自己的名望而隐瞒和篡改它。"我不也在做一样的事吗。我给韦托里写信，说自己白天砍柴晚上换朝服，那不就是一种篡改？把一个被流放的人，写成配得上写《君主论》的样子。我写这些碎片的时候，到底是在记，还是在给自己塑像。……分不清。可能本来就分不清。',-1),e("hr",null,null,-1),e("p",null,"自然会在躯体积了太多多余之物时自行清洗，人类这种复杂的躯体也一样——人满为患、无处可去的时候，狡诈与邪恶就登峰造极，于是世界得靠瘟疫、洪水、灾荒来清洗一遍，人少了、受了挫，才重新变良善。这是我最冷的一段话，冷到我自己都抖。可是冷，不代表我不信。我见过佛罗伦萨，见过意大利，见过人挤到没有退路之后会做出什么。我信这话，就像信机运主宰一半的行动。可如果清洗终会来，那我此刻拼了命写的这些，又算什么呢。是被洪水冲走前，一个不肯松手的人。",-1),e("hr",null,null,-1),e("p",null,'托斯卡纳曾经极强大，有信仰、有德行、有风俗，还有自己的古老语言——这一切都被罗马的强权灭了。如今还留在世上的，唯其名称。就一个名字。我数着我的佛罗伦萨，它有信仰吗，有德行吗，有它自己的语言吗？它什么都在丢掉，连名字都越来越轻。我写《论李维》，一章一章地写，有时候觉得我不是在论古人，我是在给自己提前挖一座碑，刻上"这里埋着一个懂得一切、却什么也留不住的人"。托斯卡纳只剩名字了。我连名字，都不确定留得下。',-1)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
